        tok = peek()
        if tok in ('+', '-'):
            advance()
            val = parse_unary()
            return val if tok == '+' else -val
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            advance()
            # exponent may start with unary sign
            exp = parse_unary()
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if e < 0 and base == 0:
