        tok = peek()
        if tok == '(':
            advance()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses")
            advance()
            return val
        if isinstance(tok, int):
            advance()
            return Fraction(tok)
        raise ValueError("syntax error")

